"""Source-checked draft solutions to §§8–9; printed pp.85–87,94–98.
All coordinates are author-created schematic models. Never imports other authors.
"""
from pathlib import Path
from copy import deepcopy
import json, math
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'stereo-course/merzlyak-10-base/lessons'
OUT.mkdir(parents=True,exist_ok=True)
COVER={}
INDEX=json.loads((ROOT/'stereo-course/merzlyak-10-base/source-index.json').read_text())
SOURCES={e['source'].get('exercise'):e for e in INDEX['entries'] if e['source'].get('collection')=='main'}

def mid(a,b,t=.5):return [(1-t)*x+t*y for x,y in zip(a,b)]
def point(m,n,p):m['points'][n]=[round(float(x),9) for x in p];return n
def at(m,n,a,b,t=.5):return point(m,n,mid(m['points'][a],m['points'][b],t))
def model(p,e=(),f=(),planar=False):return {'points':deepcopy(p),'edges':[list(x) for x in e],'faces':[list(x) for x in f],'labelNames':[],'planar':planar,'views':{'neutral':{'label':'Данные задачи','points':[n for n in p if not n.startswith('_')][:8]}}}
def view(m,k,label,seg=(),poly=(),pts=()):
 v={'label':label}
 if seg:v['segments']=[list(x) for x in seg]
 if poly:v['polygon']=list(poly)
 if pts:v['points']=list(pts)
 m['views'][k]=v;return k

def cube(a=1,h=None):
 if h is None:h=a
 p={'A':[0,0,0],'B':[0,a,0],'C':[a,a,0],'D':[a,0,0],'A1':[0,0,h],'B1':[0,a,h],'C1':[a,a,h],'D1':[a,0,h]}
 return model(p,[('A','B'),('B','C'),('C','D'),('D','A'),('A1','B1'),('B1','C1'),('C1','D1'),('D1','A1'),('A','A1'),('B','B1'),('C','C1'),('D','D1')],[('A','B','C','D'),('A1','B1','C1','D1'),('A','B','B1','A1'),('B','C','C1','B1'),('C','D','D1','C1'),('D','A','A1','D1')])
def tetra(p=None):
 p=p or {'A':[0,0,0],'B':[1,0,0],'C':[.5,math.sqrt(3)/2,0],'D':[.5,math.sqrt(3)/6,math.sqrt(2/3)]}
 return model(p,[('A','B'),('B','C'),('C','A'),('A','D'),('B','D'),('C','D')],[('A','B','C'),('A','B','D'),('B','C','D'),('C','A','D')])
def base4(p):return model(p,[('A','B'),('B','C'),('C','D'),('D','A')],[('A','B','C','D')])
def plane(m,z=0,size=2,name='p'):
 names=['_'+name+str(i) for i in range(4)]
 for n,p in zip(names,[[-size,-size,z],[size,-size,z],[size,size,z],[-size,size,z]]):point(m,n,p)
 m['faces'].append(names)
 return names

def st(title,text,v='neutral',why='Используем данное условие и свойства указанной фигуры.',prompt=None):return {'title':title,'prompt':prompt or title+' — выполните этот шаг самостоятельно.','explanation':text,'view':v,'justifications':[{'kind':'theorem','text':why}]}
def save(p,n,title,statement,m,steps,answer=None,sub=None,hint=None):
 num=f'{p}.{n}';id=f'ex-{p:02d}-{n:03d}'+('-'+str(sub) if sub else '')
 src=deepcopy(SOURCES[num]['source']);src.pop('paragraph',None)
 if sub:src['subpart']=str(sub)
 for i,s in enumerate(steps,1):s['id']=f'step-{i}'
 assert 3<=len(steps)<=7,(id,len(steps))
 d={'schemaVersion':1,'revision':1,'id':id,'kind':'exercise','title':num+(f'({sub})' if sub else '')+'. '+title,'status':'draft','source':src,'statement':{'text':statement,'goal':title+'. Обоснуйте результат.'},'visualization':{'type':'scene3d','caption':'Авторская схема условия и построения. Координаты подобраны для наглядности; длины и углы следует доказывать, а не измерять по изображению.','model':m},'help':[{'id':'help-1','question':'Подсказка к первому шагу','text':hint or steps[0]['explanation']}],'steps':steps,'answer':{'mode':'manual','prompt':answer or 'Запишите доказательство или ответ и объясните каждый переход. Доказательство обсуждается с учителем и автоматически не оценивается.'},'review':{'source':'pending','mathematics':'pending','pedagogy':'pending'}}
 (OUT/(id+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
 c=COVER.setdefault(num,{'sourceId':SOURCES[num]['id'],'exercise':num,'printedPages':src['printedPages'],'pdfPages':src['pdfPages'],'requiredParts':[],'lessonIds':[]})
 c['requiredParts'].append(str(sub) if sub else None);c['lessonIds'].append(id)

# §8. Definition includes perpendicular skew lines.
m=model({'O':[0,0,0],'A':[0,0,2],'B':[0,0,-2],'P':[1,0,0],'Q':[1,1.5,0],'R':[-1,1,0]},[('A','B')]);plane(m,0,1.5)
view(m,'on','Через O: разные направления в перпендикулярной плоскости',[('O','P'),('O','Q'),('O','R')],pts=['O','P','Q','R'])
view(m,'off','Через внешнюю точку P',[('P','O'),('P','Q'),('P','R')],pts=['P','O','Q','R'])
save(8,1,'Число перпендикуляров','Сколько прямых, перпендикулярных данной прямой, можно провести через точку: 1) принадлежащую этой прямой; 2) не принадлежащую ей?',m,[st('Определение','Прямые в пространстве перпендикулярны, если угол между ними равен 90°. Они могут пересекаться или быть скрещивающимися.'),st('Точка на прямой','1) В плоскости через O, перпендикулярной AB, каждая прямая через O перпендикулярна AB. Таких прямых бесконечно много.','on'),st('Внешняя точка','2) Через P в плоскости, перпендикулярной AB, также проходит бесконечно много прямых. Все имеют угол 90° с AB. Только одна из них пересекает AB; остальные скрещиваются с ней.','off')],answer='В обоих случаях бесконечно много; поясните роль скрещивающихся прямых.')
for n,pairs,results,explain in [(2,[('C','D','B','C'),('A','A1','C1','D1'),('A','A1','D1','C'),('A','C','B1','D1'),('A1','C1','A','C')],['90°','90°','45°','90°','0°'],['Соседние стороны квадрата ABCD перпендикулярны.','AA₁ ∥ CC₁, а CC₁ ⟂ C₁D₁.','AA₁ ∥ DD₁; диагональ D₁C квадратной грани образует с DD₁ угол 45°.','B₁D₁ ∥ BD, а диагонали квадрата AC и BD перпендикулярны.','Диагонали соответствующих параллельных граней A₁C₁ и AC параллельны.']),(3,[('A','B','B','B1'),('A','B','B1','D1'),('A1','D','B1','C'),('B1','D1','C1','C')],['90°','45°','0°','90°'],['AB и BB₁ — соседние стороны квадратной грани.','AB ∥ A₁B₁; диагональ B₁D₁ делит прямой угол верхнего квадрата пополам.','Диагонали A₁D и B₁C соответствующих граней параллельны.','C₁C перпендикулярна верхней грани, следовательно, её диагонали B₁D₁.'])]:
 m=cube();ss=[]
 for i,(pair,r,t) in enumerate(zip(pairs,results,explain),1):
  a,b,c,d=pair;view(m,'p'+str(i),'Пара '+str(i),[(a,b),(c,d)],pts=list(dict.fromkeys(pair)))
  ss.append(st('Пара '+str(i),t+' Ответ: '+r+'.','p'+str(i),'Угол между прямыми сохраняется при параллельном переносе; свойства квадрата.'))
 save(8,n,'Углы между прямыми куба','Дан куб ABCDA₁B₁C₁D₁. Найдите углы между прямыми: '+'; '.join(f'{i}) '+f'{a}{b} и {c}{d}'.replace('1','₁') for i,(a,b,c,d) in enumerate(pairs,1))+'.',m,ss,answer='Ответы по порядку: '+', '.join(results)+'.')
m=base4({'A':[0,0,0],'B':[2,0,0],'C':[2,1,0],'D':[0,1,0],'M':[1,1,math.sqrt(3)]});m['edges'] += [['M','C'],['M','D']];view(m,'angle','Перенос AB к CD',[('A','B'),('C','D'),('C','M')],pts=['A','B','C','D','M'])
save(8,4,'Угол с боковой стороной равностороннего треугольника','M не принадлежит плоскости прямоугольника ABCD. Треугольник CMD равносторонний. Найдите угол между AB и MC.',m,[st('Параллельная сторона','В прямоугольнике AB ∥ CD. Поэтому угол между AB и MC равен углу между CD и MC.','angle'),st('Угол треугольника','Все углы равностороннего CMD равны 60°, в частности ∠DCM=60°.','angle'),st('Выбор меньшего угла','60° не превышает 90°, значит это и есть угол между прямыми. Ответ: 60°.','angle')])
m=base4({'A':[0,0,0],'B':[0,1,0],'C':[1,1,0],'D':[1,0,0],'M':[0,1-math.cos(math.radians(40)),math.sin(math.radians(40))]});m['edges'] += [['M','B']];view(m,'p1','AD параллельна BC',[('A','D'),('B','C'),('B','M')],pts=['A','B','C','D','M']);view(m,'p2','CD параллельна AB',[('C','D'),('A','B'),('B','M')],pts=['A','B','C','D','M'])
save(8,5,'Два угла с прямой MB','M вне плоскости квадрата ABCD, ∠MBA=40°, ∠MBC=90°. Найдите углы между: 1) MB и AD; 2) MB и CD.',m,[st('Параллельные стороны','В квадрате AD ∥ BC, CD ∥ AB.'),st('Первый угол','1) Угол MB с AD равен углу MB с BC: 90°.','p1'),st('Второй угол','2) Угол MB с CD равен углу MB с AB: 40°. Оба выбранных угла не больше 90°.','p2')])
m=base4({'A':[-2,0,0],'B':[-1,1,0],'C':[1,1,0],'D':[2,0,0]});at(m,'E','A','B');at(m,'F','C','D');point(m,'M',[-1.5+3*math.cos(math.radians(110)),.5,3*math.sin(math.radians(110))]);m['edges'] += [['M','E'],['M','F']];view(m,'tri','Равнобедренный треугольник MEF',poly=['M','E','F'],pts=['M','E','F']);view(m,'base','Средняя линия трапеции',[('E','F'),('A','D'),('B','C')],pts=['A','B','C','D','E','F'])
save(8,6,'Три угла со средней линией','В трапеции ABCD основания AD и BC. E и F — середины AB и CD. Треугольник MEF не лежит в плоскости трапеции, ME=FE, ∠MEF=110°. Найдите углы между: 1) AD и EF; 2) AD и ME; 3) BC и MF.',m,[st('Средняя линия','EF ∥ AD ∥ BC, так как E,F — середины боковых сторон трапеции. Поэтому 1) угол AD и EF равен 0°.','base'),st('Тупой угол заменяем смежным','2) Угол AD и ME равен углу EF и ME. Меньший из смежных углов — 180°−110°=70°.','tri'),st('Углы при основании','ME=FE, поэтому ∠EMF=∠MFE=(180°−110°)/2=35°. Из BC ∥ EF получаем 3) угол BC и MF равен 35°.','tri')])
