save(9,30,'Высоты вершин параллелограмма','Параллелограмм ABCD не пересекает плоскость α. Перпендикуляры к α из A,B,D равны 11,18,16 см. Найдите длину перпендикуляра из C.',m,[st('Общая середина','Пусть O — точка пересечения диагоналей. Она является серединой AC и BD. Все вершины по одну сторону α.','diags'),st('Средняя высота','В плоскости перпендикуляров из B,D отрезок OO₁ — средняя линия трапеции BDD₁B₁. Поэтому hO=(18+16)/2=17. Аналогично hO=(hA+hC)/2.','diags'),st('Искомая высота','17=(11+hC)/2, откуда hC=34−11=23 см.','diags')])
