save(9,38,'Косинус угла двух прямых','E — середина ребра DD₁ куба ABCDA₁B₁C₁D₁. Найдите косинус угла между AB₁ и A₁E.',m,[st('Параллельная прямая','Пусть K — середина CC₁. Отрезки A₁E и B₁K параллельны как соответствующие отрезки параллельных граней. Искомый угол равен углу AB₁ с B₁K.','transfer'),st('Три стороны','Пусть ребро равно a. AB₁=a√2. В прямоугольном B₁C₁K: B₁K²=a²+(a/2)²=5a²/4. В прямоугольном ACK: AK²=AC²+CK²=2a²+a²/4=9a²/4.','tri'),st('Теорема косинусов','cos∠AB₁K=(AB₁²+B₁K²−AK²)/(2·AB₁·B₁K)=(2+5/4−9/4)/(2√2·√5/2)=1/√10=√10/10.','tri'),st('Угол между прямыми','Полученный косинус положителен, поэтому ∠AB₁K острый и является искомым углом между прямыми. Ответ: √10/10.','tri')])
